def solve(clue):
    T = clue.split()
    n = int(T[0])
    adj = [[] for _ in range(n)]
    for e in T[1:]:
        a, b = e.split('-')
        adj[int(a)].append(int(b))
        adj[int(b)].append(int(a))
    col = [-1] * n
    order = sorted(range(n), key=lambda v: -len(adj[v]))

    def bt(i):
        if i == n:
            return True
        v = order[i]
        for k in range(3):
            if all(col[u] != k for u in adj[v]):
                col[v] = k
                if bt(i + 1):
                    return True
                col[v] = -1
        return False

    bt(0)
    return ''.join(str(max(x, 0)) for x in col)

